onSubmit:
{{
  (async () => {
    try {
      const txt = Input_Scan_CodeBarre.text?.trim().toLowerCase();
      const qteAjo = Number(Input_Qt_Scan.text) || 1;
      if (!txt) return;

      const data = Array.isArray(Table_Achats.tableData) ? Table_Achats.tableData : [];
      const storeSelection = appsmith.store.carton_selection || {};

      // 1. Filtrer les articles pointés (en BDD OU dans le store Appsmith)
      const correspondances = data.filter(r => {
        const estPointee = (r.Dans_Carton_En_Cours === true || storeSelection[r.ID_Ligne_Achat] === true);
        const matchText = (r.Ref_Fournisseur && r.Ref_Fournisseur.toLowerCase().includes(txt)) ||
                          (r.Code_Barre && r.Code_Barre.toLowerCase() === txt) || // 🟢 AJOUT DU SCAN CODE BARRE
                          (r.Article_Designation && r.Article_Designation.toLowerCase().includes(txt)) ||
                          (r.ID_Article && r.ID_Article.toLowerCase().includes(txt));
        return estPointee && matchText;
      });

      if (correspondances.length === 0) {
        await storeValue('lastScanResult', {
          title: `❌ ARTICLE INCONNU OU NON POINTÉ`,
          detail: `Aucune ligne cochée sur ce BL ne correspond à "${txt}"`
        });
        resetWidget('Input_Scan_CodeBarre', true);
        return;
      }

      // 2. Sélectionner en priorité la première ligne NON COMPLÈTE parmi les doublons
      const nonCompletes = correspondances.filter(r => {
        const qteScanne = Number(r.Livraison_Du_Jour) || 0;
        const qteAttendue = Number(r.Quantite_BL) || Number(r.Quantite) || 0;
        return qteScanne < qteAttendue;
      });

      const art = nonCompletes.length > 0 ? nonCompletes[0] : correspondances[0];

      // 3. Exécution de la fonction SQL Supabase
      const resQuery = await Run_Scan_FIFO.run({
        idLigne: art.ID_Ligne_Achat,
        qteScan: qteAjo
      });

      // 4. Extraction et décodage robuste du JSON
      let reponse = resQuery?.[0]?.result || resQuery?.[0]?.fn_traiter_scan_fifo || resQuery?.[0];

      if (typeof reponse === 'string') {
        try { reponse = JSON.parse(reponse); } catch (e) {}
      }

      if (reponse && (reponse.success || reponse.title)) {
        await storeValue('lastScanResult', {
          title: reponse.title,
          detail: reponse.detail
        });
      }

      // 5. Rafraîchissement des données et nettoyage
      await Get_Achats_Pool.run();
      resetWidget('Input_Scan_CodeBarre', true);
      resetWidget('Input_Qt_Scan', true);

    } catch (err) {
      showAlert('Erreur lors du scan : ' + err.message, 'error');
    }
  })()
}}
